public class AVLTree {
    class Node { int val, height; Node left, right;
        Node(int v){val=v;height=1;} }
    int height(Node n){return n==null?0:n.height;}
    int balance(Node n){return n==null?0:height(n.left)-height(n.right);}
    Node rotateRight(Node y){Node x=y.left,T2=x.right;x.right=y;y.left=T2;y.height=1+Math.max(height(y.left),height(y.right));x.height=1+Math.max(height(x.left),height(x.right));return x;}
    Node rotateLeft(Node x){Node y=x.right,T2=y.left;y.left=x;x.right=T2;x.height=1+Math.max(height(x.left),height(x.right));y.height=1+Math.max(height(y.left),height(y.right));return y;}
    Node insert(Node node,int key){if(node==null)return new Node(key);if(key<node.val)node.left=insert(node.left,key);else if(key>node.val)node.right=insert(node.right,key);else return node;node.height=1+Math.max(height(node.left),height(node.right));int bf=balance(node);if(bf>1&&key<node.left.val)return rotateRight(node);if(bf<-1&&key>node.right.val)return rotateLeft(node);if(bf>1&&key>node.left.val){node.left=rotateLeft(node.left);return rotateRight(node);}if(bf<-1&&key<node.right.val){node.right=rotateRight(node.right);return rotateLeft(node);}return node;}
}

