#include <algorithm>
using namespace std;
struct Node{int v,h;Node*l,*r;Node(int x):v(x),h(1),l(nullptr),r(nullptr){}};
int ht(Node*n){return n?n->h:0;}
int bf(Node*n){return n?ht(n->l)-ht(n->r):0;}
Node* rR(Node*y){Node*x=y->l;y->l=x->r;x->r=y;y->h=1+max(ht(y->l),ht(y->r));x->h=1+max(ht(x->l),ht(x->r));return x;}
Node* rL(Node*x){Node*y=x->r;x->r=y->l;y->l=x;x->h=1+max(ht(x->l),ht(x->r));y->h=1+max(ht(y->l),ht(y->r));return y;}
